    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= occupied:
                for i, j in square:
                    out[i][j] = 1
                    remaining.discard((i, j))

    # Color residual connected components according to their position.
    seen = set()
    components = []
    for p in sorted(remaining):
        if p in seen:
            continue
        stack = [p]
        seen.add(p)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (r + dr, c + dc)
                if q in remaining and q not in seen:
                    seen.add(q)
                    stack.append(q)
        components.append(comp)

    for comp in components:
        top = min(r for r, c in comp)
        left = min(c for r, c in comp)
        # The pieces are L triominoes; colors distinguish the four orientations.
        color = 2 + ((top + left) % 3)
        for r, c in comp:
            out[r][c] = color

    return out
