            if box <= cells:
                tiles.append((box, 1))
            for missing in box:
                shape = box - {missing}
                if shape <= cells:
                    # Colors encode the missing corner.
                    color = {
                        (r, c): 2,          # top-left
                        (r + 1, c): 3,      # bottom-left
                        (r, c + 1): 4,      # top-right
                        (r + 1, c + 1): 5   # bottom-right
                    }[missing]
                    tiles.append((shape, color))

    by_cell = {p: [] for p in cells}
    for shape, color in tiles:
        for p in shape:
            by_cell[p].append((shape, color))

    answer = {}
    def cover(remaining):
        if not remaining:
            return True
        p = min(remaining)
        for shape, color in by_cell[p]:
            if shape <= remaining:
                for q in shape:
                    answer[q] = color
                if cover(remaining - shape):
                    return True
                for q in shape:
                    del answer[q]
        return False

    cover(set(cells))
    out = [[0] * w for _ in range(h)]
    for (r, c), color in answer.items():
        out[r][c] = color
    return out
